package com.nexus.access.backend.security; import java.io.IOException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import io.jsonwebtoken.*; import com.nexus.access.backend.auth.JwtService; import com.nexus.access.backend.user.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt;private final UserRepository users;public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String header=req.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer ")){try{Claims claims=jwt.parse(header.substring(7));User u=users.findById(java.util.UUID.fromString(claims.getSubject())).filter(user->user.isActive()).orElse(null);if(u!=null){var auth=new UsernamePasswordAuthenticationToken(u.getId().toString(),null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole())));SecurityContextHolder.getContext().setAuthentication(auth);}}catch(JwtException|IllegalArgumentException ignored){SecurityContextHolder.clearContext();}}chain.doFilter(req,res);}}
